import{_ as o,o as s,c as i,a2 as r}from"./chunks/framework.e4u2V5E7.js";const m=JSON.parse('{"title":"Linux","description":"Linux reference documentation","frontmatter":{"title":"Linux","description":"Linux reference documentation"},"headers":[],"relativePath":"knowledge/linux.md","filePath":"knowledge/linux.md","lastUpdated":1784485118000}'),t={name:"knowledge/linux.md"};function a(n,e,c,d,l,p){return s(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h1><h1 id="linux-administration-knowledge-document" tabindex="-1">Linux Administration Knowledge Document <a class="header-anchor" href="#linux-administration-knowledge-document" aria-label="Permalink to &quot;Linux Administration Knowledge Document&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Linux is the dominant operating system for servers, containers, cloud infrastructure, and embedded systems. Proficiency in Linux administration — file system management, process control, networking, security hardening, and automation — is essential for deploying, debugging, and maintaining production applications. This document covers the practical knowledge needed for day-to-day server operations.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="file-system-hierarchy" tabindex="-1">File System Hierarchy <a class="header-anchor" href="#file-system-hierarchy" aria-label="Permalink to &quot;File System Hierarchy&quot;">​</a></h3><ul><li><code>/etc/</code> — System configuration files</li><li><code>/var/</code> — Variable data (logs, caches, spools)</li><li><code>/tmp/</code> — Temporary files (cleared on reboot)</li><li><code>/home/</code> — User home directories</li><li><code>/opt/</code> — Optional/third-party software</li><li><code>/proc/</code> — Virtual filesystem for process and kernel information</li><li><code>/usr/</code> — User programs and libraries (read-only in modern systems)</li></ul><h3 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><p>Linux uses a permission model: <code>owner / group / others</code> with <code>read (r) / write (w) / execute (x)</code> bits. <code>chmod</code>, <code>chown</code>, and <code>chgrp</code> modify permissions. Special bits: <code>setuid</code> (run as file owner), <code>setgid</code> (run as file group), <code>sticky bit</code> (only owner can delete in directory).</p><h3 id="process-management" tabindex="-1">Process Management <a class="header-anchor" href="#process-management" aria-label="Permalink to &quot;Process Management&quot;">​</a></h3><p>Processes have states: running, sleeping, stopped, zombie. <code>ps</code>, <code>top</code>/<code>htop</code>, <code>kill</code>, <code>nice</code>, <code>nohup</code> manage processes. Signals: <code>SIGTERM</code> (graceful), <code>SIGKILL</code> (force), <code>SIGHUP</code> (reload config for many daemons).</p><h3 id="systemd" tabindex="-1">systemd <a class="header-anchor" href="#systemd" aria-label="Permalink to &quot;systemd&quot;">​</a></h3><p>systemd manages services (units). <code>systemctl start|stop|restart|status|enable|disable</code> controls services. <code>journalctl</code> queries systemd logs. Service files live in <code>/etc/systemd/system/</code>.</p><h3 id="package-management" tabindex="-1">Package Management <a class="header-anchor" href="#package-management" aria-label="Permalink to &quot;Package Management&quot;">​</a></h3><ul><li><strong>Debian/Ubuntu:</strong> <code>apt</code>, <code>.deb</code> packages</li><li><strong>RHEL/CentOS/Fedora:</strong> <code>dnf</code>/<code>yum</code>, <code>.rpm</code> packages</li><li><strong>Alpine:</strong> <code>apk</code>, <code>.apk</code> packages (used in Docker images)</li></ul><h3 id="networking" tabindex="-1">Networking <a class="header-anchor" href="#networking" aria-label="Permalink to &quot;Networking&quot;">​</a></h3><p><code>ip</code>, <code>ss</code>, <code>netstat</code>, <code>curl</code>, <code>wget</code>, <code>iptables</code>/<code>nftables</code>, <code>ssh</code> are essential tools. <code>ss -tlnp</code> shows listening TCP ports. DNS resolution uses <code>/etc/resolv.conf</code> and systemd-resolved.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Use SSH keys, disable password authentication</strong> — Generate Ed25519 keys (<code>ssh-keygen -t ed25519</code>). Disable <code>PasswordAuthentication no</code> in <code>/etc/ssh/sshd_config</code>. Use fail2ban for brute-force protection.</p></li><li><p><strong>Never run as root for daily tasks</strong> — Use a regular user with <code>sudo</code> for administrative tasks. Create separate service accounts for running daemons.</p></li><li><p><strong>Use <code>systemctl</code> for service management</strong> — Never use <code>service</code> or <code>/etc/init.d/</code> scripts on modern systems. systemd handles dependencies, logging, and restart policies.</p></li><li><p><strong>Set up log rotation</strong> — Configure <code>/etc/logrotate.conf</code> and application-specific configs in <code>/etc/logrotate.d/</code>. Prevent disk exhaustion from unbounded log files.</p></li><li><p><strong>Use <code>tmux</code> or <code>screen</code> for long-running processes</strong> — SSH sessions can disconnect. tmux persists sessions across disconnections and allows multiple windows.</p></li><li><p><strong>Monitor disk usage proactively</strong> — Set alerts for <code>/var/log</code>, <code>/tmp</code>, and data directories. Use <code>df -h</code> for disk space and <code>du -sh /path</code> for directory sizes.</p></li><li><p><strong>Keep systems updated</strong> — Run <code>apt update &amp;&amp; apt upgrade</code> or <code>dnf update</code> regularly. Subscribe to security mailing lists for critical patches.</p></li><li><p><strong>Use <code>journalctl -u service-name -f</code> for real-time logs</strong> — systemd&#39;s journal provides structured, searchable logs with timestamps. Use <code>--since &quot;1 hour ago&quot;</code> for time-range queries.</p></li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><p><strong>Disabling SELinux/AppArmor &quot;to fix things&quot;</strong> — These are mandatory access control systems. Instead of disabling them, write proper policies. Disabling them removes a critical security layer.</p></li><li><p><strong>Editing files with <code>echo &gt;&gt;</code> in scripts</strong> — Use <code>sed</code>, <code>awk</code>, or configuration management tools (Ansible, Puppet) for idempotent file modifications.</p></li><li><p><strong>Running services as root</strong> — Each service should run as its own user with minimal privileges. A compromised service running as root owns the entire system.</p></li><li><p><strong>Ignoring firewall rules</strong> — Configure <code>ufw</code>, <code>firewalld</code>, or <code>nftables</code> to allow only necessary ports. Default-deny inbound is essential for security.</p></li><li><p><strong>Using <code>kill -9</code> as first resort</strong> — <code>SIGKILL</code> doesn&#39;t allow graceful shutdown. Always try <code>SIGTERM</code> (kill without flag, or <code>kill -15</code>) first. Use <code>kill -9</code> only when processes refuse to terminate.</p></li><li><p><strong>Not setting timezone on servers</strong> — Use <code>timedatectl set-timezone UTC</code> on all servers. UTC prevents confusion in logs across time zones.</p></li><li><p><strong>Running <code>chmod 777</code></strong> — This gives everyone full access. Use the minimum permissions needed: <code>755</code> for directories, <code>644</code> for files, <code>600</code> for secrets.</p></li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><p><strong>Forgetting to escape special characters in shell</strong> — Use single quotes for literal strings, double quotes for variable interpolation. Characters like <code>!</code>, <code>$</code>, <code>*</code> need escaping.</p></li><li><p><strong>Not using <code>systemctl enable</code> after install</strong> — Services won&#39;t start on boot without <code>enable</code>. <code>start</code> only starts now; <code>enable</code> ensures auto-start.</p></li><li><p><strong>Ignoring swap configuration</strong> — Without swap, the OOM killer activates prematurely. Set <code>vm.swappiness=10</code> for servers to prefer RAM before swapping.</p></li><li><p><strong>Using <code>ifconfig</code> instead of <code>ip</code></strong> — <code>ifconfig</code> is deprecated. Use <code>ip addr</code>, <code>ip link</code>, <code>ip route</code> for modern network configuration.</p></li><li><p><strong>Not using <code>nohup</code> or <code>disown</code> for background processes</strong> — Processes started in a terminal are killed when the session ends. Use <code>nohup command &amp;</code> or <code>disown</code> to prevent this.</p></li><li><p><strong>Editing <code>/etc/resolv.conf</code> directly</strong> — On systemd-based systems, this file is managed by systemd-resolved. Edit <code>/etc/systemd/resolved.conf</code> instead.</p></li><li><p><strong>Not checking <code>dmesg</code> for hardware errors</strong> — <code>dmesg</code> shows kernel messages including hardware failures, OOM events, and driver issues. Check it when diagnosing unexpected crashes.</p></li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><ul><li><strong>Use systemd timers over cron</strong> — Timers provide better logging, dependency management, and missed-run handling. Cron is simpler for one-off recurring tasks.</li><li><strong>Use Alpine for containers, Debian/Ubuntu for servers</strong> — Alpine&#39;s minimal footprint is ideal for containers. Debian/Ubuntu has better package availability for servers.</li><li><strong>Use <code>rsync</code> over <code>scp</code> for file transfers</strong> — rsync handles resume, compression, permissions, and is significantly faster for large or repeated transfers.</li><li><strong>Use <code>ufw</code> for simple firewalls, <code>nftables</code> for complex rules</strong> — ufw is beginner-friendly; nftables provides advanced filtering with better performance.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Linux man pages: <code>man command</code> (e.g., <code>man ssh</code>)</li><li>The Linux Command Line (book): <a href="https://linuxcommand.org" target="_blank" rel="noreferrer">https://linuxcommand.org</a></li><li>Linux Journey: <a href="https://linuxjourney.com" target="_blank" rel="noreferrer">https://linuxjourney.com</a></li><li>ArchWiki (comprehensive): <a href="https://wiki.archlinux.org" target="_blank" rel="noreferrer">https://wiki.archlinux.org</a></li><li>DigitalOcean Community Tutorials: <a href="https://www.digitalocean.com/community/tutorials" target="_blank" rel="noreferrer">https://www.digitalocean.com/community/tutorials</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><code>alias ll=&#39;ls -alF&#39;</code> creates a useful directory listing alias. Add to <code>~/.bashrc</code>.</li><li><code>history | grep command</code> searches command history. <code>!!</code> repeats the last command.</li><li><code>ssh-copy-id user@host</code> copies SSH keys to remote servers for passwordless login.</li><li><code>crontab -e</code> edits the current user&#39;s cron jobs. Use <code>0 2 * * * /path/script.sh</code> for daily 2 AM execution.</li><li><code>htop</code> provides a better <code>top</code> with mouse support, color, and tree view.</li><li><code>curl -o /dev/null -s -w &quot;%{http_code} %{time_total}s&quot; url</code> shows HTTP status and response time.</li><li>For Docker containers based on Alpine, use <code>apk add --no-cache package</code> to avoid caching package lists.</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',31)])])}const g=o(t,[["render",a]]);export{m as __pageData,g as default};
